/*
 * A117334  Triangle, read by rows, where column 0 is [1,-1,-2,-3,...,-n,...]
 *          and column k+1 is generated by the binomial transform of column k
 *          preceded by a zero (column k includes the k zeros above the main
 *          diagonal).
 * https://oeis.org/A117334
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, tabl
 * Formula:   a(n) is the entry at linear index n in the triangle T defined by
 *            T(0,0)=1, T(n,0) = -n for n>0, and T(n,k) = Σ_{i=k..n} C(n,i) *
 *            T(i-1,k-1) for k>0
 * Range:     i8 n <= 28, i16 n <= 56, i32 n <= 63, i64 n <= 63, i128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* External linkage function required by the build */
seq_t a(idx_t n)
{
    /* Find the row that contains index n (zero‑based rows). */
    idx_t row = 0;
    while (row * (row + 1) / 2 <= n) ++row;
    row--;                                   /* largest row with start index ≤ n */
    idx_t offset = row * (row + 1) / 2;       /* first index of this row   */
    idx_t col    = n - offset;               /* column within the row     */

    /* Static storage for memoised rows of the triangle. */
    static idx_t  max_row = 0;                /* highest row computed so far */
    static seq_t **tri    = NULL;             /* pointer array to rows      */

    /* Initialise storage for row 0 if necessary. */
    if (tri == NULL) {
        tri = (seq_t**)malloc(sizeof(seq_t*));
        if (!tri) return 0; /* out of memory – unlikely for given limits  */
        seq_t *row0 = (seq_t*)malloc(sizeof(seq_t));
        if (!row0) return 0;
        row0[0] = 1;                            /* T(0,0)=1                 */
        tri[0] = row0;
        max_row = 0;
    }

    /* Compute missing rows up to the required 'row'. */
    while (row > max_row) {
        idx_t cur = max_row + 1;                /* index of new row to build */

        /* Allocate array for the new row (length cur+1). */
        seq_t *rowArr = (seq_t*)malloc((cur + 1) * sizeof(seq_t));
        if (!rowArr) return 0;                  /* out of memory */

        /* Binomial coefficients C(cur,i) for i=0..cur. */
        seq_t *bin = (seq_t*)malloc((cur + 1) * sizeof(seq_t));
        if (!bin) return 0;
        bin[0] = 1;
        for (idx_t i = 1; i <= cur; ++i) {
            /* bin[i] = bin[i-1] * (cur-i+1) / i  – exact division */
            bin[i] = bin[i - 1] * (seq_t)(cur - i + 1) / (seq_t)i;
        }

        /* Column 0 of the new row. */
        rowArr[0] = -(seq_t)cur;

        /* Remaining columns k=1..cur. */
        for (idx_t k = 1; k <= cur; ++k) {
            seq_t sum = 0;
            for (idx_t i = k; i <= cur; ++i) {
                sum += bin[i] * tri[i - 1][k - 1];
            }
            rowArr[k] = sum;
        }

        free(bin);

        /* Expand the triangle pointer array and store the new row. */
        seq_t **new_tri = (seq_t**)realloc(tri, (cur + 1) * sizeof(seq_t*));
        if (!new_tri) return 0;
        tri = new_tri;
        tri[cur] = rowArr;
        max_row = cur;
    }

    return tri[row][col];
}
